def get_binary(num, bits):
	ans = []
	for i in range(bits):
		ans.append('0')
	i = bits - 1
	while i >= 0:
		ans[i] = str(num % 2)
		num //= 2
		i -= 1
	return ''.join(ans)
for t in range(int(input())):
	temp = list(input().split())
	k = int(temp[0])
	s = temp[1]
	ans = []
	for i in range(2 ** k):
		ans.append('0')
	for i in range(2 ** k):
		bi = get_binary(i, k)
		bi = bi[::-1]
		x = eval('0b' + bi)
		ans[x] = s[i]
	print(''.join(ans))
